from pathlib import Path
import re

p=Path('index.html')
s=p.read_text(encoding='utf-8')
original=s

def once(old,new,label):
    global s
    n=s.count(old)
    if n!=1:
        raise SystemExit(f'{label}: expected 1 anchor, found {n}')
    s=s.replace(old,new,1)

def remove_balanced_div_containing(marker,label):
    global s
    pos=s.find(marker)
    if pos<0:
        raise SystemExit(f'{label}: marker not found')
    starts=[m.start() for m in re.finditer(r'<div\b',s[:pos],re.I)]
    for start in reversed(starts):
        mclass=re.match(r'<div\b[^>]*>',s[start:],re.I|re.S)
        if not mclass: continue
        tag=mclass.group(0)
        if 'clean-card' not in tag and label not in ('smart rules',):
            continue
        depth=0
        for m in re.finditer(r'</?div\b[^>]*>',s[start:],re.I|re.S):
            if m.group(0).lower().startswith('</div'):
                depth-=1
                if depth==0:
                    end=start+m.end()
                    if start<=pos<=end:
                        s=s[:start]+s[end:]
                        return
            else:
                depth+=1
    raise SystemExit(f'{label}: containing card not found')

